import { ArrowLeftIcon } from '@heroicons/react/solid';
import { AnimatePresence } from 'framer-motion';
import { Link, useLocation } from 'react-router-dom';

interface Props {
  children: React.ReactNode;
  className?: string;
  dialogVisible?: boolean;
  dialogContent?: React.ReactNode;
  onDialogClose?: (value?: any) => void;
}

export default function Layout({
  children,
  className,
  dialogVisible = false,
  dialogContent,
  onDialogClose,
}: Props) {
  return (
    <div
      className={`relative select-none w-full  h-full xl:container mx-auto px-5 py-10 ${className}`}
    >
      {children}

      <AnimatePresence exitBeforeEnter>
        {dialogVisible && dialogContent && (
          <div className='fixed top-0 left-0 right-0 bottom-0 bg-black bg-opacity-60 flex items-center justify-center z-10'>
            {dialogContent}
          </div>
        )}
      </AnimatePresence>
    </div>
  );
}
